using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using WebApplication1;
using WebApplication1.Data;
using MvcBookstore.Models;
namespace MvcBookstore.Controllers;

[Authorize(Policy = Permissions.Admin), Route("Admin")]
public partial class AdminController(AppDbContext db, UserManager<ApplicationUser> users, RoleManager<IdentityRole> roles, IWebHostEnvironment env) : Controller
{
    [HttpGet(""), HttpGet("Index")] public async Task<IActionResult> Index() => View(new DashboardModel { Products = await db.Products.CountAsync(), Customers = await db.Customers.CountAsync(), Categories = await db.Categories.CountAsync(), Orders = await db.Orders.CountAsync(), Revenue = await db.Set<OrderLine>().Where(x => x.Order.Status == "Completed").SumAsync(x => (decimal?)x.UnitPrice * x.Quantity) ?? 0 });
    [Authorize(Policy = Permissions.Products), HttpGet("Products")] public async Task<IActionResult> Products(string? search) { var q = db.Products.AsNoTracking(); if (!string.IsNullOrWhiteSpace(search)) q = q.Where(x => x.Name.Contains(search) || x.Author.Contains(search) || x.Category.Contains(search)); return View(new ProductsModel { Search = search, Items = await q.ToListAsync() }); }
    [Authorize(Policy = Permissions.Products), HttpPost("DeleteProduct")] public async Task<IActionResult> DeleteProduct(int id) { var x = await db.Products.FindAsync(id); if (x is null) return NotFound(); db.Products.Remove(x); await db.SaveChangesAsync(); return RedirectToAction(nameof(Products)); }
    [Authorize(Policy = Permissions.Products), HttpGet("ProductEdit")] public async Task<IActionResult> ProductEdit(int id = 0) { var m = new ProductEditModel { Categories = await db.Categories.ToListAsync() }; if (id != 0) { var x = await db.Products.FindAsync(id); if (x is null) return NotFound(); m.Input = new() { Id = x.Id, Name = x.Name, Description = x.Description, Category = x.Category, CategoryId = x.CategoryId ?? 0, Price = x.Price, Author = x.Author, Publisher = x.Publisher, PublicationYear = x.PublicationYear, Isbn = x.Isbn, PageCount = x.PageCount, ColorClass = x.ColorClass }; m.Preview = x.ImageUrl; } return View(m); }
    [Authorize(Policy = Permissions.Products), HttpPost("ProductEdit"), RequestSizeLimit(3 * 1024 * 1024)]
    public async Task<IActionResult> ProductEdit(ProductEditModel model)
    {
        var input = model.Input; var old = input.Id == 0 ? null : await db.Products.AsNoTracking().FirstOrDefaultAsync(x => x.Id == input.Id); if (input.Id != 0 && old is null) return NotFound(); model.Preview = old?.ImageUrl; model.Categories = await db.Categories.ToListAsync();
        var category = await db.Categories.FindAsync(input.CategoryId); ModelState.Remove("Input.Category"); if (category is null) ModelState.AddModelError("", "Chọn danh mục hợp lệ."); if (!ModelState.IsValid) return View(model); string? uploaded = null;
        try { if (model.Cover is not null) uploaded = await ProductImages.SaveAsync(model.Cover, ProductImages.Root(env.ContentRootPath)); var product = new Product(input.Id, input.Name.Trim(), input.Description.Trim(), category!.Name, input.Price, "", input.ColorClass, uploaded ?? (model.RemoveImage ? null : old?.ImageUrl), input.Author.Trim(), input.Publisher?.Trim() ?? "", input.PublicationYear, input.Isbn?.Trim() ?? "", input.PageCount) { CategoryId = category.Id }; if (input.Id == 0) db.Products.Add(product); else db.Products.Update(product); await db.SaveChangesAsync(); TempData["Message"] = "Đã lưu sách."; return RedirectToAction(nameof(Products)); } catch (Exception ex) when (ex is InvalidDataException or IOException or DbUpdateException) { if (uploaded is not null) System.IO.File.Delete(Path.Combine(ProductImages.Root(env.ContentRootPath), Path.GetFileName(uploaded))); ModelState.AddModelError("", ex is InvalidDataException ? ex.Message : "Không thể lưu sách."); return View(model); }
    }
    [Authorize(Policy = Permissions.Customers), HttpGet("Customers")] public async Task<IActionResult> Customers(string? search) { var q = db.Customers.AsNoTracking(); if (!string.IsNullOrWhiteSpace(search)) q = q.Where(x => x.Name.Contains(search) || x.Email.Contains(search) || x.Phone.Contains(search)); return View(new CustomersModel { Search = search, Items = await q.ToListAsync() }); }
    [Authorize(Policy = Permissions.Customers), HttpGet("CustomerEdit")] public async Task<IActionResult> CustomerEdit(int id = 0) { var m = new CustomerEditModel(); if (id != 0) { var x = await db.Customers.FindAsync(id); if (x is null) return NotFound(); m.Input = new() { Id = x.Id, Name = x.Name, Email = x.Email, Phone = x.Phone, Address = x.Address }; } return View(m); }
    [Authorize(Policy = Permissions.Customers), HttpPost("CustomerEdit")]
    public async Task<IActionResult> CustomerEdit(CustomerEditModel model)
    {
        var input = model.Input; if (!ModelState.IsValid) return View(model); if (input.Id != 0 && !await db.Customers.AnyAsync(x => x.Id == input.Id)) return NotFound(); if (await db.Customers.AnyAsync(x => x.Id != input.Id && x.Email == input.Email) || await db.Users.AnyAsync(x => x.CustomerId != input.Id && x.Email == input.Email)) { ModelState.AddModelError("", "Email đã tồn tại."); return View(model); }
        await using var tx = await db.Database.BeginTransactionAsync(); var customer = new Customer(input.Id, input.Name.Trim(), input.Email.Trim(), input.Phone.Trim(), input.Address?.Trim() ?? ""); if (input.Id == 0) db.Customers.Add(customer); else db.Customers.Update(customer); var account = await db.Users.FirstOrDefaultAsync(x => x.CustomerId == input.Id); if (account is not null) { account.FullName = customer.Name; account.Email = customer.Email; account.PhoneNumber = customer.Phone; var result = await users.UpdateAsync(account); if (!result.Succeeded) { foreach (var e in result.Errors) ModelState.AddModelError("", e.Description); return View(model); } await users.UpdateSecurityStampAsync(account); }
        await db.SaveChangesAsync(); await tx.CommitAsync(); TempData["Message"] = "Đã lưu khách hàng."; return RedirectToAction(nameof(Customers));
    }
    [Authorize(Policy = Permissions.Customers), HttpPost("DeleteCustomer")] public async Task<IActionResult> DeleteCustomer(int id) { if (await db.Users.AnyAsync(x => x.CustomerId == id) || await db.Orders.AnyAsync(x => x.CustomerId == id) || await db.Accounts.AnyAsync(x => x.CustomerId == id)) { TempData["Message"] = "Không thể xóa khách hàng có tài khoản hoặc đơn hàng."; return RedirectToAction(nameof(Customers)); } var x = await db.Customers.FindAsync(id); if (x is null) return NotFound(); db.Customers.Remove(x); await db.SaveChangesAsync(); return RedirectToAction(nameof(Customers)); }
    [Authorize(Policy = Permissions.Categories), HttpGet("Categories")] public async Task<IActionResult> Categories(string? search, int id = 0) { var input = id == 0 ? new Category() : await db.Categories.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id); if (input is null) return NotFound(); return View(new CategoriesModel { Search = search, Input = input, Items = await db.Categories.AsNoTracking().Where(x => search == null || x.Name.Contains(search)).ToListAsync() }); }
    [Authorize(Policy = Permissions.Categories), HttpPost("SaveCategory")]
    public async Task<IActionResult> SaveCategory(Category input)
    {
        if (await db.Categories.AnyAsync(x => x.Id != input.Id && x.Name == input.Name)) ModelState.AddModelError("", "Tên danh mục đã tồn tại."); if (!ModelState.IsValid) return View("Categories", new CategoriesModel { Input = input, Items = await db.Categories.AsNoTracking().ToListAsync() });
        input.Name = input.Name.Trim(); input.Description ??= ""; if (input.Id == 0) db.Categories.Add(input); else { var old = await db.Categories.FindAsync(input.Id); if (old is null) return NotFound(); old.Name = input.Name; old.Description = input.Description ?? ""; foreach (var p in await db.Products.Where(x => x.CategoryId == old.Id).ToListAsync()) db.Entry(p).Property(x => x.Category).CurrentValue = old.Name; }
        await db.SaveChangesAsync(); return RedirectToAction(nameof(Categories));
    }
    [Authorize(Policy = Permissions.Categories), HttpPost("DeleteCategory")] public async Task<IActionResult> DeleteCategory(int id) { if (await db.Products.AnyAsync(x => x.CategoryId == id)) { TempData["Message"] = "Danh mục đang có sách."; return RedirectToAction(nameof(Categories)); } var x = await db.Categories.FindAsync(id); if (x is null) return NotFound(); db.Categories.Remove(x); await db.SaveChangesAsync(); return RedirectToAction(nameof(Categories)); }
    [Authorize(Policy = Permissions.Orders), HttpGet("Orders")] public async Task<IActionResult> Orders(string? search, string? status) { var q = db.Orders.AsNoTracking().Include(x => x.Customer).Include(x => x.Lines).AsQueryable(); if (!string.IsNullOrWhiteSpace(search)) q = q.Where(x => x.Customer.Name.Contains(search) || x.Customer.Email.Contains(search) || x.Id.ToString() == search); if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status); return View(new OrdersModel { Search = search, Status = status, Items = await q.OrderByDescending(x => x.Id).ToListAsync() }); }
    [Authorize(Policy = Permissions.Orders), HttpPost("DeleteOrder")] public async Task<IActionResult> DeleteOrder(int id) { var x = await db.Orders.FindAsync(id); if (x is null) return NotFound(); db.Orders.Remove(x); await db.SaveChangesAsync(); return RedirectToAction(nameof(Orders)); }
    [Authorize(Policy = Permissions.Orders), HttpPost("OrderStatus")] public async Task<IActionResult> OrderStatus(int id, string status) { if (!OrderStatuses.All.ContainsKey(status)) return BadRequest(); var x = await db.Orders.FindAsync(id); if (x is null) return NotFound(); x.Status = status; await db.SaveChangesAsync(); return RedirectToAction(nameof(Orders)); }
}


